// 把上传的名片图转 base64 data URL，并构建 OCR 请求
const bin = $input.item.binary || {};
const keys = Object.keys(bin);
if (keys.length === 0) { throw new Error('未收到名片图片，请确认已上传文件'); }
const key = keys[0];
const meta = bin[key];
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const b64 = buffer.toString('base64');
const mime = (meta && meta.mimeType) || 'image/jpeg';
const dataUrl = 'data:' + mime + ';base64,' + b64;
const body = $input.item.json.body || $input.item.json;
const salesOwner = body['负责销售'] || body['sale'] || '';
return [{ json: {
  sales_owner: salesOwner,
  ai_payload: {
    model: 'Qwen/Qwen3-VL-32B-Instruct',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: "\u4f60\u662f\u540d\u7247\u4fe1\u606f\u63d0\u53d6\u5668\u3002\u4ece\u56fe\u7247\u4e2d\u63d0\u53d6\u8054\u7cfb\u4eba\u5b57\u6bb5\uff0c\u53ea\u8f93\u51faJSON\uff1a{\"name\":\"\",\"company\":\"\",\"title\":\"\",\"phone\":\"\",\"email\":\"\",\"country\":\"\"}\u3002\u8bc6\u522b\u4e0d\u5230\u7684\u5b57\u6bb5\u586bnull\uff0c\u4e0d\u8981\u7f16\u9020\u3002phone\u542b\u56fd\u5bb6\u7801\u5e76\u53bb\u6389\u7a7a\u683c\u4e0e\u7b26\u53f7\u3002" },
      { role: 'user', content: [
        { type: 'image_url', image_url: { url: dataUrl } },
        { type: 'text', text: '提取这张名片的联系人信息。' }
      ]}
    ]
  }
}}];

var raw=($input.first().json.choices&&$input.first().json.choices[0]&&$input.first().json.choices[0].message&&$input.first().json.choices[0].message.content)||'{}';
var c;try{c=JSON.parse(raw);}catch(e){c={};}
var sales=$('读图并构建请求').item.json.sales_owner||'';
return [{json:{card:c,feishu_body:{fields:{
  '客户号码':c.phone||'', '姓名':c.name||'', '公司':c.company||'', '职位':c.title||'',
  '邮箱':c.email||'', '国家':c.country||'', '来源':'展会', '负责销售':sales,
  '审核状态':'待审核', '跟进状态':'新线索'
}}}}];
